# 单词覆盖链：按长度排序，DP 求最长覆盖链并输出。
import sys

def main():
    raw = sys.stdin.read()
    words = [ln.strip() for ln in raw.split('\n') if ln.strip()]
    if not words:
        return
    words.sort(key=len)
    n = len(words)
    cc = [[0] * 26 for _ in range(n)]
    for i, w in enumerate(words):
        for ch in w:
            cc[i][ord(ch) - 97] += 1
    f = [1] * n
    pre = list(range(n))
    for i in range(n):
        for j in range(i):
            if all(cc[i][c] >= cc[j][c] for c in range(26)):
                if f[j] + 1 > f[i]:
                    f[i] = f[j] + 1
                    pre[i] = j
    res = 0
    for i in range(n):
        if f[i] > f[res]:
            res = i
    chain = []
    x = res
    while True:
        chain.append(words[x])
        if pre[x] == x:
            break
        x = pre[x]
    chain.reverse()
    print(len(chain))
    for w in chain:
        print(w)

if __name__ == '__main__':
    main()

