import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<String> list = new ArrayList<>();
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (!line.isEmpty()) list.add(line);
        }
        if (list.isEmpty()) return;
        list.sort(Comparator.comparingInt(String::length));
        int n = list.size();
        int[][] cc = new int[n][26];
        for (int i = 0; i < n; i++)
            for (char ch : list.get(i).toCharArray()) cc[i][ch - 'a']++;
        int[] f = new int[n];
        int[] pre = new int[n];
        Arrays.fill(f, 1);
        for (int i = 0; i < n; i++) pre[i] = i;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                boolean ok = true;
                for (int c = 0; c < 26; c++) if (cc[i][c] < cc[j][c]) { ok = false; break; }
                if (ok && f[j] + 1 > f[i]) { f[i] = f[j] + 1; pre[i] = j; }
            }
        }
        int res = 0;
        for (int i = 0; i < n; i++) if (f[i] > f[res]) res = i;
        List<String> chain = new ArrayList<>();
        int x = res;
        while (true) {
            chain.add(list.get(x));
            if (pre[x] == x) break;
            x = pre[x];
        }
        Collections.reverse(chain);
        System.out.println(chain.size());
        for (String w : chain) System.out.println(w);
    }
}
